import XCTest
@testable import ColorComposerCore

/// Replays the solver parity corpus published by the `color_matching`
/// backend (`viamin/color_matching`, `priv/parity/v1/corpus.json`).
///
/// The corpus is generated by the server's own solver, so replaying it is
/// what keeps the mirrored `WeightedSquaredErrorScorer` and the app's
/// earliest-wins selection honest: every scenario pins the per-candidate
/// scores, the selection, the tie evidence, and the exclusion behavior.
final class SolverParityCorpusTests: XCTestCase {
    private var corpus: ParityCorpus!

    override func setUpWithError() throws {
        try super.setUpWithError()
        corpus = try ParityCorpusFixture.load()
    }

    override func tearDown() {
        corpus = nil
        super.tearDown()
    }

    // MARK: - Corpus integrity

    /// The committed corpus must stay byte-identical to the upstream artifact
    /// it was copied from: refreshing it is a deliberate act, not a side
    /// effect of editing the file.
    func testCommittedCorpusMatchesThePublishedFingerprint() throws {
        let data = try Data(contentsOf: try ParityCorpusFixture.fileURL())

        XCTAssertEqual(
            ParityCorpusFixture.fingerprint(of: data),
            ParityCorpusFixture.expectedFingerprint,
            "The committed parity corpus changed. Copy the upstream corpus over "
                + "\(ParityCorpusFixture.relativePath) and update "
                + "ParityCorpusFixture.expectedFingerprint when refreshing it."
        )
    }

    /// The corpus header describes the solver and selection contract this app
    /// mirrors; a change there means the mirrored semantics changed too.
    func testCorpusDescribesThePublishedSolverContract() {
        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])
    }

    /// The corpus is the shared source of truth, so the scenarios it covers —
    /// ties, missing-measurement exclusions, weight handling — must not
    /// silently disappear from the committed copy.
    func testCorpusCoversTiesExclusionsAndWeightHandling() {
        XCTAssertEqual(
            Set(corpus.scenarios.map(\.id)),
            [
                "distinct-errors",
                "tie-symmetric-around-target",
                "tie-duplicate-vectors",
                "tie-three-way-on-lps",
                "missing-candidate-excluded",
                "missing-target-excluded",
                "zero-weight-channel-missing",
                "all-excluded",
                "single-channel-lps",
                "exact-match-zero-error",
                "unknown-weight-ignored",
                "mixed-large-palette"
            ]
        )
    }

    // MARK: - Scoring parity

    /// Every candidate of every scenario scores exactly like the server's
    /// scorer, including the candidates the server excludes.
    func testScorerScoresMatchCorpusExpectations() {
        for scenario in corpus.scenarios {
            let results = scores(for: scenario)
            XCTAssertEqual(results.count, scenario.expected.scores.count, scenario.id)

            for expected in scenario.expected.scores {
                guard expected.index < results.count else {
                    XCTFail("\(scenario.id): expected score for index \(expected.index) is out of range")
                    continue
                }
                assert(result: results[expected.index], matches: expected.score, scenario: scenario.id, index: expected.index)
            }
        }
    }

    /// The selection the app makes must be the selection the server makes:
    /// the lowest score wins, ties go to the earliest candidate, and excluded
    /// candidates never win.
    func testScorerSelectionMatchesCorpusExpectations() throws {
        for scenario in corpus.scenarios {
            let results = scores(for: scenario)

            guard let winner = earliestBest(in: results) else {
                XCTAssertNil(scenario.expected.selectedIndex, "\(scenario.id): expected no selection")
                XCTAssertNil(scenario.expected.selectedHexColor, "\(scenario.id): expected no selection")
                XCTAssertNil(scenario.expected.error, "\(scenario.id): expected no selection")
                XCTAssertEqual(scenario.expected.tiedIndices, [], "\(scenario.id): expected no tied candidates")
                continue
            }

            XCTAssertEqual(winner.index, scenario.expected.selectedIndex, scenario.id)
            XCTAssertEqual(
                palette(for: scenario)[winner.index].hex,
                scenario.expected.selectedHexColor,
                scenario.id
            )
            XCTAssertEqual(
                winner.score,
                try XCTUnwrap(scenario.expected.error, "\(scenario.id): expected an error"),
                accuracy: 1e-12,
                scenario.id
            )
        }
    }

    /// The corpus records which candidates tied for the best score; the app
    /// must see exactly the same tie set, and must resolve it the same way.
    func testTieEvidenceMatchesCorpusExpectations() {
        for scenario in corpus.scenarios {
            let results = scores(for: scenario)

            guard let winner = earliestBest(in: results) else {
                XCTAssertEqual(scenario.expected.tiedIndices, [], scenario.id)
                continue
            }

            let tied = results.enumerated().compactMap { index, result -> Int? in
                guard case .score(let score) = result, score == winner.score else { return nil }
                return index
            }
            XCTAssertEqual(tied, scenario.expected.tiedIndices, scenario.id)
            XCTAssertEqual(scenario.expected.tieBroke, tied.count > 1, scenario.id)
        }
    }

    /// Tie cases are the ones where client and server silently disagree, so
    /// the corpus must keep several of them and each must resolve to the
    /// earliest tied candidate.
    func testTieScenariosSelectTheEarliestTiedCandidate() {
        let tieScenarios = corpus.scenarios.filter { $0.expected.tieBroke == true }
        XCTAssertGreaterThanOrEqual(tieScenarios.count, 4)

        for scenario in tieScenarios {
            let tied = scenario.expected.tiedIndices
            XCTAssertGreaterThan(tied.count, 1, scenario.id)
            XCTAssertEqual(scenario.expected.selectedIndex, tied.first, scenario.id)
        }
    }

    // MARK: - Solver parity

    /// The full solver — the path the app actually takes when composing — must
    /// land on the corpus winner for every scenario.
    func testSolverSelectsTheCorpusWinner() throws {
        for scenario in corpus.scenarios {
            let weights = weights(for: scenario)
            let target = target(for: scenario)
            let palette = palette(for: scenario)
            let solver = CompositionSolver(scorer: WeightedSquaredErrorScorer())

            let missingCondition = weights.activeConditions.first { target.value(for: $0) == nil }
            if let missingCondition {
                // A target without a measurement for a weighted channel cannot
                // be composed at all: the server excludes every candidate.
                XCTAssertThrowsError(
                    try solver.solve(palette: palette, sourceGrids: [:], weights: weights),
                    "\(scenario.id)"
                ) { error in
                    XCTAssertEqual(
                        error as? CompositionSolverError,
                        .missingSourceGrid(missingCondition),
                        scenario.id
                    )
                }
                XCTAssertNil(scenario.expected.selectedIndex, scenario.id)
                continue
            }

            var grids: [LightingCondition: BrightnessGrid] = [:]
            for condition in weights.activeConditions {
                grids[condition] = BrightnessGrid(
                    width: 1,
                    height: 1,
                    fill: target.value(for: condition) ?? 0
                )
            }

            let result = try solver.solve(palette: palette, sourceGrids: grids, weights: weights)

            guard let selectedIndex = result.colorIndex(x: 0, y: 0) else {
                XCTAssertNil(scenario.expected.selectedIndex, "\(scenario.id): expected no selection")
                continue
            }

            XCTAssertEqual(selectedIndex, scenario.expected.selectedIndex, scenario.id)
            XCTAssertEqual(
                palette[selectedIndex].hex,
                scenario.expected.selectedHexColor,
                scenario.id
            )
            XCTAssertEqual(
                result.error(x: 0, y: 0),
                try XCTUnwrap(scenario.expected.error, "\(scenario.id): expected an error"),
                accuracy: 1e-12,
                scenario.id
            )
        }
    }

    /// Candidates the server excludes stay excluded for the app: a palette
    /// whose every color misses a weighted channel yields no selection.
    func testSolverLeavesUnmatchedCellsWhenEveryCandidateIsExcluded() throws {
        let scenario = try XCTUnwrap(corpus.scenarios.first { $0.id == "all-excluded" })
        let weights = weights(for: scenario)
        let target = target(for: scenario)
        let palette = palette(for: scenario)

        var grids: [LightingCondition: BrightnessGrid] = [:]
        for condition in weights.activeConditions {
            grids[condition] = BrightnessGrid(width: 1, height: 1, fill: target.value(for: condition) ?? 0)
        }

        let result = try CompositionSolver(scorer: WeightedSquaredErrorScorer())
            .solve(palette: palette, sourceGrids: grids, weights: weights)

        XCTAssertEqual(result.unmatchedCellCount, 1)
        XCTAssertEqual(result.colorIndex(x: 0, y: 0), nil)
        XCTAssertEqual(result.error(x: 0, y: 0), Double.infinity)
        XCTAssertEqual(result.excludedCandidateCount, palette.count)
    }

    // MARK: - Helpers

    /// The app's weights, ignoring light sources the app cannot measure (the
    /// corpus's "unknown weight" scenario carries one on purpose).
    private func weights(for scenario: ParityScenario) -> ChannelWeights {
        var weights = ChannelWeights()
        for (source, weight) in scenario.weights {
            guard let condition = LightingCondition(rawValue: source) else { continue }
            switch condition {
            case .white: weights.white = weight
            case .red: weights.red = weight
            case .green: weights.green = weight
            case .blue: weights.blue = weight
            case .lps: weights.lps = weight
            }
        }
        return weights
    }

    /// The target vector; channels the corpus does not list are missing.
    private func target(for scenario: ParityScenario) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (source, value) in scenario.target.channels {
            guard let condition = LightingCondition(rawValue: source) else { continue }
            brightness[condition] = value
        }
        return TargetResponseVector(brightness)
    }

    /// The palette, in corpus order, with unmeasured channels left absent.
    private func palette(for scenario: ParityScenario) -> [PaletteColor] {
        scenario.palette.enumerated().map { index, entry in
            var responses: [LightingCondition: IlluminationResponse] = [:]
            for (source, value) in entry.channels {
                guard let condition = LightingCondition(rawValue: source) else { continue }
                responses[condition] = IlluminationResponse(brightness: value)
            }
            return PaletteColor(
                id: index,
                hex: entry.hexColor,
                rgb: RGBColor(hex: entry.hexColor) ?? RGBColor(red: 0, green: 0, blue: 0),
                responses: responses
            )
        }
    }

    /// Scores every candidate of a scenario with the mirrored scorer.
    private func scores(for scenario: ParityScenario) -> [ScorerResult] {
        let scorer = WeightedSquaredErrorScorer()
        let weights = weights(for: scenario)
        let target = target(for: scenario)
        return palette(for: scenario).map {
            scorer.score(candidate: $0, target: target, weights: weights)
        }
    }

    /// The lowest scoring candidate, earliest index winning a tie.
    private func earliestBest(in results: [ScorerResult]) -> (index: Int, score: Double)? {
        var best: (index: Int, score: Double)?
        for (index, result) in results.enumerated() {
            guard case .score(let score) = result else { continue }
            if best == nil || score < best!.score {
                best = (index, score)
            }
        }
        return best
    }

    private func assert(
        result: ScorerResult,
        matches expected: ParityScoreValue,
        scenario: String,
        index: Int
    ) {
        switch (expected, result) {
        case (.excluded, .excluded):
            return
        case (.value(let expectedScore), .score(let actualScore)):
            XCTAssertEqual(actualScore, expectedScore, accuracy: 1e-12, "\(scenario) candidate \(index)")
        case (.excluded, .score(let actualScore)):
            XCTFail("\(scenario) candidate \(index): expected .excluded but scored \(actualScore)")
        case (.value(let expectedScore), .excluded):
            XCTFail("\(scenario) candidate \(index): expected \(expectedScore) but was excluded")
        }
    }
}
